def budget(start):
    elapsed = time.monotonic() - start
    rss = psutil.Process().memory_info().rss
    if elapsed > LIMIT_SECONDS:
        raise TimeoutError("METH-14 15-minute CPU stop")
    if rss > LIMIT_RSS:
        raise MemoryError("METH-14 20-GiB process RAM stop")
    return elapsed, rss


